const {make}=require('./audit-mechanics-four.cjs'),vm=require('node:vm'),assert=require('node:assert/strict');
const results=[];const test=(name,fn)=>{try{fn();results.push({name,ok:true})}catch(e){results.push({name,ok:false,error:e.message})}};
function sample(state,yaw,pitch){const t=make('elevator');vm.runInContext(`globalThis.masks={};globalThis.supports=[];const E=window.ElevatorOcclusion;for(const name of['maskBox','maskRod','maskPrism']){const old=E[name];E[name]=(...a)=>{if(name==='maskBox')masks[a[0]]={faces:E.boxFaces(...a[1]),solids:a[3].filter(q=>!(Array.isArray(q)&&q.every((v,i)=>v===a[1][i])))};if(name==='maskRod')masks[a[0]]={faces:E.rodFaces(a[1],a[2],a[3],a[6]?.segments),solids:a[5]};if(name==='maskPrism')masks[a[0]]={faces:a[1],solids:a[3]};return old(...a)}}const originalRod=rod;rod=(...a)=>{supports.push(a.slice(0,3));return originalRod(...a)};globalThis.hiddenAt=(key,q)=>{const x=masks[key],p=P(...q),h=E.hiddenPolygons(key,x.faces,x.solids,{padding:0});return h.some(poly=>{let sign=0;for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],c=(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);if(Math.abs(c)<1e-7)continue;if(sign&&Math.sign(c)!==sign)return false;sign=Math.sign(c)}return true})};`,t.ctx);Object.assign(t.state,state);t.ctx.draw(yaw,pitch);return t;}
test('Integrated cable is hidden behind the closed second-floor landing',()=>{const t=sample({},0,35);assert(t.ctx.hiddenAt('cable',[30.35,33,45]));assert(t.ctx.layers().find(p=>p.key==='cable').depthTested)});
test('Counterweight guide shoes occlude rails when car is at the top floor',()=>{const t=sample({floor:3,pos:66},90,35);assert(t.ctx.hiddenAt('weightRail20',[20,50.55,9]));assert(t.ctx.hiddenAt('weightRail36',[36,50.55,9]))});
test('Counterweight top crossbeam occludes upper plate instead of being erased',()=>{const t=sample({floor:3,pos:66},45,27);assert(t.ctx.hiddenAt('weight-block5',[25.2,50.2,29]))});
test('Backside landing locks are masked by their solid header',()=>{const t=sample({},135,27);assert(t.ctx.hiddenAt('landingLock0body',[42.9,26,34.2]))});
test('Far tangent rope is hidden locally by the sheave rim',()=>{const t=sample({},45,35);assert(t.ctx.hiddenAt('upperRope',[30,33,123]));assert(t.ctx.layers().find(p=>p.key==='upperRope').depthTested)});
test('Cabin handrail has two real wall-connected supports',()=>{const t=sample({},72,22);const supports=t.ctx.supports.filter(([a,b])=>a[0]===10&&b[0]===12&&a[2]===18.5&&a[1]===b[1]);assert.equal(supports.length,2);assert.deepEqual(Array.from(supports,([a])=>a[1]),[15,40])});
test('High back view hides drive axle inside motor casing and wheel hub',()=>{const t=sample({pos:33},110,78);assert(t.ctx.hiddenAt('driveAxle',[26.8,41.5,124.25]));assert(t.ctx.layers().find(p=>p.key==='driveAxle').depthTested)});
console.log(JSON.stringify(results,null,2));assert(results.every(t=>t.ok));
